-- Recipes part 1/4: insert-only.
do $seed$
declare d jsonb := '[{"slug":"chicken-jalfrezi","name":"Chicken Jalfrezi","description":"Boneless chicken stir-fried on high heat with capsicum, onion, tomato and green chillies in a tangy masala.","category":"Main Course","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":2,"salty":5,"sour":4,"spicy":7},"lines":[["Chicken Boneless (Boti)",600,"600 g, in strips"],["Capsicum",200,"2, in thick strips"],["Onion",200,"2 medium, in wedges"],["Tomato",250,"3 medium, chopped"],["Green Chilli",20,"4, slit"],["Ginger",15,"1 tbsp paste, plus a little julienned"],["Garlic",10,"2 tsp paste"],["Cooking Oil",60,"1/4 cup"],["Salt",6,"1 tsp"],["Red Chilli Powder",4,"1 tsp"],["Turmeric (Haldi)",1,"1/4 tsp"],["Coriander Powder",4,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Black Pepper",2,"1/2 tsp"],["Vinegar",15,"1 tbsp"],["Fresh Coriander",10,"to garnish"]],"steps":["Heat the oil on high heat and sear the chicken with the ginger and garlic for 5-6 minutes until lightly golden.","Add the tomatoes, salt, red chilli, turmeric, coriander powder and cumin; cook until the tomatoes break down and the oil separates.","Add the onion and capsicum and stir-fry on high heat for 3-4 minutes so they stay crunchy.","Add the green chillies, black pepper and vinegar; toss for 1 minute.","Garnish with julienned ginger and coriander. Serve hot with naan or plain rice."]},{"slug":"chicken-achari","name":"Chicken Achari","description":"Chicken in a tangy yogurt and tomato gravy flavoured with the pickling spices of a Pakistani achar.","category":"Main Course","cuisine":"Pakistani","minutes":45,"servings":4,"taste":{"sweet":1,"salty":6,"sour":7,"spicy":7},"lines":[["Chicken Leg Piece",750,"750 g, cut in pieces"],["Onion",200,"2 medium, sliced"],["Tomato",250,"3 medium, chopped"],["Yogurt (Dahi)",150,"2/3 cup, whisked"],["Green Chilli",20,"4, slit"],["Ginger",15,"1 tbsp paste"],["Garlic",15,"1 tbsp paste"],["Mustard Oil",60,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Turmeric (Haldi)",1,"1/4 tsp"],["Fennel Seeds (Saunf)",4,"2 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Mustard Seeds (Sarson)",3,"1 tsp"],["Fenugreek (Methi Dana)",2,"1/2 tsp"],["Nigella Seeds (Kalonji)",2,"1/2 tsp"],["Lemon",30,"juice of 1"],["Fresh Coriander",10,"to garnish"]],"steps":["Dry-roast the fennel, cumin, mustard, fenugreek and nigella for 1 minute until fragrant, then lightly crush them.","Heat the mustard oil until it just smokes, lower the heat and fry the onion until golden.","Add the chicken, ginger and garlic and cook on high heat for 6-7 minutes until the chicken changes colour.","Add the tomatoes, salt, red chilli, turmeric and half the crushed spices; cook until the oil separates.","Lower the heat, stir in the yogurt, cover and cook for 12-15 minutes until the chicken is tender.","Add the slit green chillies, the remaining spices and the lemon juice; simmer for 2 minutes, garnish with coriander and serve."]},{"slug":"butter-chicken","name":"Butter Chicken","description":"Grilled chicken pieces simmered in a smooth, buttery tomato and cream gravy.","category":"Main Course","cuisine":"Pakistani","minutes":50,"servings":4,"taste":{"sweet":4,"salty":5,"sour":3,"spicy":4},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Yogurt (Dahi)",120,"1/2 cup"],["Tomato",400,"4 medium, pureed"],["Butter (Makhan)",50,"4 tbsp"],["Fresh Cream (Malai)",100,"1/2 cup"],["Ginger Garlic Paste",20,"1 tbsp"],["Kashmiri Chilli Powder",6,"2 tsp"],["Garam Masala",3,"1 tsp"],["Kasuri Methi",2,"1 tsp"],["Salt",7,"1 1/4 tsp"],["White Sugar",5,"1 tsp"]],"steps":["Marinate the chicken with yogurt, half the ginger garlic paste, chilli powder and salt for 30 minutes.","Sear the chicken in a hot pan until charred at the edges; set aside.","Melt the butter, add the rest of the ginger garlic paste and the tomato puree; cook until thick and glossy (10 minutes).","Add the chicken, garam masala, sugar and crushed kasuri methi; simmer for 8 minutes.","Stir in the cream, warm through and serve with naan."]},{"slug":"chicken-white-karahi","name":"White Chicken Karahi","description":"A creamy, peppery karahi made with yogurt and cream instead of tomatoes.","category":"Main Course","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Chicken Leg Piece",750,"750 g"],["Yogurt (Dahi)",200,"3/4 cup"],["Fresh Cream (Malai)",100,"1/2 cup"],["Ginger Garlic Paste",20,"1 tbsp"],["Green Chilli",25,"5, slit"],["Black Pepper",4,"1 tsp, crushed"],["White Pepper",2,"1/2 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",50,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Ginger",10,"julienned"]],"steps":["Fry the chicken in the oil with the ginger garlic paste until it turns white.","Add salt, both peppers and cumin; stir for 2 minutes.","Add the whisked yogurt and cook on high heat until the chicken is tender and the oil shows (12 minutes).","Add green chillies and cream, cook for 3 minutes and finish with julienned ginger."]},{"slug":"chicken-malai-boti","name":"Chicken Malai Boti","description":"Tender boneless chicken marinated in cream, cheese and mild spices, then grilled.","category":"Snacks","cuisine":"Pakistani","minutes":45,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":3},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Fresh Cream (Malai)",80,"1/3 cup"],["Yogurt (Dahi)",60,"1/4 cup"],["Processed Cheese Slice",40,"2 slices"],["Ginger Garlic Paste",15,"1 tbsp"],["White Pepper",3,"1 tsp"],["Green Chilli",10,"2, ground"],["Lemon",15,"juice of 1/2"],["Salt",6,"1 tsp"],["Butter (Makhan)",20,"for basting"]],"steps":["Blend cream, yogurt, cheese, ginger garlic paste, green chilli, white pepper, lemon juice and salt.","Coat the chicken and marinate for at least 1 hour.","Thread onto skewers and grill or bake at 220 °C for 15-18 minutes, basting with butter.","Rest for 2 minutes and serve with mint chutney."]},{"slug":"chicken-kofta-curry","name":"Chicken Kofta Curry","description":"Soft minced-chicken meatballs cooked in a spiced onion-tomato gravy.","category":"Main Course","cuisine":"Pakistani","minutes":55,"servings":4,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Chicken Qeema",500,"500 g"],["Onion",250,"2, 1 grated for koftas"],["Tomato",250,"2 large"],["Gram Flour (Besan)",20,"2 tbsp"],["Ginger Garlic Paste",20,"1 tbsp"],["Green Chilli",10,"2"],["Red Chilli Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Garam Masala",3,"1 tsp"],["Yogurt (Dahi)",100,"1/2 cup"],["Cooking Oil",60,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Mix the qeema with grated onion, besan, half the garam masala, green chilli and salt; shape into small balls.","Fry the sliced onion in oil until golden, add ginger garlic paste, tomatoes and spices; bhuno until the oil separates.","Add yogurt and 1 cup water and bring to a simmer.","Slide in the koftas, cover and cook on low heat for 20 minutes without stirring.","Finish with garam masala and coriander."]},{"slug":"chicken-haleem","name":"Chicken Haleem","description":"Slow-cooked lentils, cracked wheat and shredded chicken, beaten into a thick, hearty stew.","category":"Main Course","cuisine":"Pakistani","minutes":150,"servings":6,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Chicken Boneless (Boti)",600,"600 g"],["Cracked Wheat (Dalia)",150,"3/4 cup, soaked"],["Chana Dal",60,"1/3 cup"],["Masoor Dal",40,"1/4 cup"],["Moong Dal",40,"1/4 cup"],["Mash Dal",40,"1/4 cup"],["Onion",300,"3, sliced and fried"],["Ginger Garlic Paste",30,"2 tbsp"],["Red Chilli Powder",8,"2 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Garam Masala",4,"1 tsp"],["Cooking Oil",100,"1/2 cup"],["Salt",12,"2 tsp"],["Lemon",30,"to serve"],["Fresh Mint (Pudina)",10,"to serve"]],"steps":["Boil the soaked wheat and all dals with turmeric until completely soft (about 1 hour).","Cook the chicken with ginger garlic paste, chilli, salt and half the fried onion until tender; shred it.","Combine the chicken with the lentils and beat (ghotna) over low heat for 30 minutes until stringy and thick.","Add garam masala and adjust salt.","Serve topped with fried onion, mint, ginger and lemon."]},{"slug":"chicken-steam-roast","name":"Chicken Steam Roast","description":"Whole chicken marinated in yogurt and spices, steamed until tender and then pan-roasted.","category":"Main Course","cuisine":"Pakistani","minutes":70,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Whole Chicken",1200,"1 small chicken, skinned, slashed"],["Yogurt (Dahi)",150,"2/3 cup"],["Lemon",30,"juice of 1"],["Ginger Garlic Paste",25,"1 1/2 tbsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Tikka Masala",15,"1 1/2 tbsp"],["Black Pepper",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",10,"1 3/4 tsp"]],"steps":["Mix yogurt, lemon, ginger garlic paste, chilli, tikka masala, pepper and salt; rub into the chicken and marinate for 2 hours.","Steam the chicken for 30-35 minutes until cooked through.","Heat the oil and roast the chicken on all sides until browned, spooning the juices over it.","Serve with salad and chutney."]},{"slug":"mutton-qorma","name":"Mutton Qorma","description":"Slow-cooked mutton in a rich fried-onion, yogurt and whole-spice gravy.","category":"Main Course","cuisine":"Pakistani","minutes":120,"servings":6,"taste":{"sweet":2,"salty":6,"sour":2,"spicy":5},"lines":[["Mutton",1000,"1 kg"],["Onion",300,"3, sliced and fried golden"],["Yogurt (Dahi)",250,"1 cup"],["Ginger Garlic Paste",30,"2 tbsp"],["Korma Masala",30,"3 tbsp"],["Green Cardamom (Elaichi)",2,"4"],["Cloves (Laung)",1,"4"],["Cinnamon (Dalchini)",2,"1 stick"],["Cooking Oil",120,"1/2 cup"],["Salt",12,"2 tsp"],["Kewra Water",5,"1 tsp"]],"steps":["Heat the oil with the whole spices, add the mutton and ginger garlic paste and brown well.","Add the yogurt blended with the crushed fried onion, korma masala and salt.","Add 2 cups water, cover and cook on low heat for 1 1/2 hours until the meat is very tender.","Cook uncovered until the oil rises, sprinkle kewra and serve with naan."]},{"slug":"mutton-paya","name":"Mutton Paya","description":"Trotters slow-cooked overnight into a sticky, spiced broth, a classic winter breakfast.","category":"Main Course","cuisine":"Pakistani","minutes":300,"servings":6,"taste":{"sweet":0,"salty":6,"sour":2,"spicy":7},"lines":[["Mutton Paya",1500,"6-8 trotters, cleaned"],["Onion",250,"2, sliced"],["Ginger Garlic Paste",40,"2 1/2 tbsp"],["Red Chilli Powder",10,"2 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Coriander Powder",8,"2 tsp"],["Garam Masala",5,"1 tsp"],["Yogurt (Dahi)",120,"1/2 cup"],["Cooking Oil",120,"1/2 cup"],["Salt",15,"2 1/2 tsp"],["Ginger",15,"julienned"],["Lemon",30,"to serve"]],"steps":["Fry the onions until golden; add ginger garlic paste and the spices with a splash of water.","Add the trotters and yogurt and bhuno for 15 minutes.","Add 3 litres of water and simmer covered for 4-5 hours (or overnight) until the meat falls off the bone.","Adjust salt and garam masala; serve with ginger, green chillies and lemon."]},{"slug":"raan-roast","name":"Mutton Raan Roast","description":"A whole leg of mutton marinated overnight and slow-roasted until it falls apart.","category":"Main Course","cuisine":"Pakistani","minutes":180,"servings":6,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Mutton Leg (Raan)",1800,"1 leg, deeply slashed"],["Yogurt (Dahi)",250,"1 cup"],["Raw Mango (Kairi)",50,"or 2 tbsp papaya paste"],["Ginger Garlic Paste",40,"2 1/2 tbsp"],["Red Chilli Powder",10,"2 tsp"],["Garam Masala",6,"1 1/2 tsp"],["Lemon",40,"juice of 1"],["Cooking Oil",60,"1/4 cup"],["Salt",15,"2 1/2 tsp"]],"steps":["Blend yogurt, raw mango, ginger garlic paste, chilli, garam masala, lemon and salt.","Rub into the leg and marinate overnight in the fridge.","Cook covered with 1 cup water on low heat (or bake at 160 °C) for 2 1/2 hours until tender.","Uncover, baste with oil and roast until browned. Serve with naan and salad."]},{"slug":"beef-seekh-kabab","name":"Beef Seekh Kabab","description":"Spiced beef mince pressed onto skewers and grilled until smoky.","category":"Snacks","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":0,"salty":6,"sour":2,"spicy":6},"lines":[["Beef Qeema",600,"600 g, double minced"],["Onion",100,"1, grated and squeezed"],["Ginger Garlic Paste",15,"1 tbsp"],["Green Chilli",15,"3, finely chopped"],["Fresh Coriander",10,"chopped"],["Red Chilli Flakes (Kuti Lal Mirch)",4,"1 tsp"],["Garam Masala",3,"1 tsp"],["Roasted Chana",20,"2 tbsp, ground"],["Salt",8,"1 1/2 tsp"],["Butter (Makhan)",20,"for basting"]],"steps":["Mix all ingredients except the butter and knead for 5 minutes; rest for 30 minutes.","Wet your hands and press the mixture onto skewers.","Grill over high heat for 10-12 minutes, turning and basting with butter.","Serve with onion rings, lemon and mint chutney."]}]'::jsonb; r jsonb; rid bigint; i int; missing text;
begin
select string_agg(distinct l->>0, ', ') into missing from jsonb_array_elements(d) r2, jsonb_array_elements(r2->'lines') l where not exists (select 1 from public.ingredients x where x.name = l->>0);
if missing is not null then raise exception 'Unknown ingredients: %', missing; end if;
for r in select * from jsonb_array_elements(d) loop
insert into public.curated_recipes(slug, name, description, category, cuisine, minutes, servings, taste, status, source) values (r->>'slug', r->>'name', r->>'description', r->>'category', r->>'cuisine', (r->>'minutes')::int, (r->>'servings')::int, r->'taste', 'published', 'curated') on conflict (slug) do nothing returning id into rid;
continue when rid is null;
for i in 0 .. jsonb_array_length(r->'lines') - 1 loop
insert into public.recipe_ingredients(recipe_id, ingredient_id, position, grams, display) select rid, x.id, i + 1, (r->'lines'->i->>1)::numeric, r->'lines'->i->>2 from public.ingredients x where x.name = r->'lines'->i->>0;
end loop;
for i in 0 .. jsonb_array_length(r->'steps') - 1 loop
insert into public.recipe_steps(recipe_id, position, body) values (rid, i + 1, r->'steps'->>i);
end loop;
end loop;
end $seed$;
select count(*) as published_recipes from public.curated_recipes where status = 'published';